from pathlib import Path
from PIL import Image
import json
OUT=Path(__file__).resolve().parent
refs=[]
for kind in ('vivant','cadavre'):
 path=OUT/f'references/059-{kind}-t1-native-512.png'
 Image.open(OUT/f'tiles/059-{kind}.png').resize((512,512),Image.Resampling.NEAREST).save(path)
 refs.append(str(path))
job=dict(number=59,source='sources/059-r4.png',source_kind='pair',tool='built-in imagegen',transparent_background=True,referenced_image_paths=refs,prompt='Edit the two supplied TRUE native32x32 pixel sprites of the SAME T-1 inspired tracked robot. Reference 1 is its living sprite; reference 2 is its collapsed dry wreck, both enlarged by nearest-neighbor. Keep this EXACT broad silhouette, overall dimensions, T-1 construction, two tracks, central elevated torso, two attached lateral rotary gun pods, stance and collapsed pose. This is a PIXEL CLEANUP, not a new design. The present gray metal/track texture is too busy at32px: remove all checkerboard reflections, small disconnected highlights, fine diagonal striping and mottled steel pixels. Draw each track as ONE coherent dark closed caterpillar tread shape with ONE large medium-gray interior wheel/roller mass, with only two or three large tread notches, not alternating bright/dark pixel patterns. Central angular torso has ONE broad light STEEL face and ONE large dark shadow plane separated by a clear silhouette edge; maximum3 gray values per material. Keep the waist dark and the torso distinct from the two track blocks. Gun housings are broad dark RED/MAROON blocks; BOTH straight rotary barrels remain unmistakable and firmly connected, light steel barrel ridge and dark squared muzzle, do not make either gun into a hand. Simplify each upper sensor to one dark square shape inside one gray frame; no extra heads. Keep all red paint on actual gun/shoulder housing surfaces, no red droplets. No green, purple, violet, lime or turquoise. Limit to about12-16 meaningful colors, strong dark pixel outline, sharply separated large masses. The robot should have a deliberate coarse32x32 pixel GRID, not a detailed100px illustration reduced to32. Do not add realistic texture, gradients, microdetails, cables, particles, surface scratches, text or shadows. Wide transparent output with exactly TWO separated subjects LEFT active cleaned robot and RIGHT cleaned dry collapsed wreck. Preserve actual alpha transparent margins and generous space between subjects. Both same scale and color/material assignment as supplied targets. No blood, stains, any fluid pool, oil, smoke, sparks, ground or background. All shape edits remain inside the original robot silhouette except removal of surface speckle; no new limbs or equipment.')
(OUT/'t1-cleanup-prompt.json').write_text(json.dumps(job,ensure_ascii=False,indent=2),encoding='utf-8')
print('Native references prepared; no source pixels changed.')
